const {fitDataAsync} = DataScience;
const linear = NeuralNet.ACTIVATIONS.linear;
const nn = NeuralNet
.builder()
.input(2)
.layer(10)
.layer(10, NeuralNet.ACTIVATIONS.sigmoid)
.layer(1, linear)
.build();

const trainXs = NArray.range(0, 500).map(() => [3 * (2 * Math.random() - 1), 3 * (2 * Math.random() - 1)]);
const testXs = NArray.range(0, 500).map(() => [3 * (2 * Math.random() - 1), 3 * (2 * Math.random() - 1)]);
const sinc = (x, y) => Math.sin(x * x + y * y) / (x * x + y * y);
const yf = ([x, y]) => sinc(x, y) + 0.1 * (2 * Math.random() - 1);

const plot = IO.plotPointCloud(trainXs.map(([x, y]) => [x, y, yf([x, y])]), {color: [1, 0, 0]});
const surface = plot.add([], {color: [0, 0, 1]});

const updateSurface = theta => {
    nn.setWeights(theta);
    surface.update(testXs.map(([x, y]) => [x, y, nn.eval([x, y])]));
    plot.render();
};

setTimeout(async () => {
    const {theta} = await fitDataAsync(trainXs, trainXs.map(yf), nn.model, {
        epochs: 10000,
        batch: 128,
        continuationEvery: 10,
        continuationFn: ({theta}) => updateSurface(theta),
    });
    updateSurface(theta);
});
plot;
